export function makeNoteRepository(config: Config): NoteRepository {
  if (config.storage === "postgres") {
    return new PostgresNoteRepository(config.databaseUrl);
  }
  return new InMemoryNoteRepository();
}

export function makeCreateNote(config: Config): CreateNote {
  return new CreateNote(makeNoteRepository(config), new UuidGenerator(), new SystemClock());
}

